#include <chrono>
#include <cstdlib>
#include <iostream>
#include <algorithm>
#include <vector>
#include <numeric>
#include <random>
#include <functional>

// ─── Custom QuickSort (Hoare partition, median-of-3 pivot, no introsort) ───

static void hoare_partition(std::vector<double>& a, int& left, int& right) {
    double mid = a[left + (right - left) / 2];
    while (left <= right) {
        while (a[left] < mid) ++left;
        while (a[right] > mid) --right;
        if (left <= right) {
            std::swap(a[left], a[right]);
            ++left;
            --right;
        }
    }
}

static void quick_sort_hoare(std::vector<double>& a, int left, int right) {
    if (left >= right) return;
    int k = left, j = right;
    hoare_partition(a, k, j);
    quick_sort_hoare(a, left, j);
    quick_sort_hoare(a, k, right);
}

void custom_quick_sort(std::vector<double>& a) {
    quick_sort_hoare(a, 0, static_cast<int>(a.size()) - 1);
}

// ─── Custom QuickSort with InsertionSort for small subarrays ───

static void insertion_sort(std::vector<double>& a, int left, int right) {
    for (int i = left + 1; i <= right; ++i) {
        double key = a[i];
        auto j = i - 1;
        while (j >= left && a[j] > key) {
            a[j + 1] = a[j];
            --j;
        }
        a[j + 1] = key;
    }
}

void custom_quick_sort_hybrid(std::vector<double>& a, int left, int right) {
    const int INSERTION_THRESHOLD = 16;
    if (right - left < INSERTION_THRESHOLD) {
        insertion_sort(a, left, right);
        return;
    }
    int k = left, j = right;
    hoare_partition(a, k, j);
    custom_quick_sort_hybrid(a, left, j);
    custom_quick_sort_hybrid(a, k, right);
}

void custom_quick_sort_hybrid_wrapper(std::vector<double>& a) {
    custom_quick_sort_hybrid(a, 0, static_cast<int>(a.size()) - 1);
}

// ─── Benchmark harness ───

using Clock = std::chrono::high_resolution_clock;

double measure_ms(std::function<void()> fn, int repetitions = 3) {
    std::vector<double> times;
    for (int i = 0; i < repetitions; ++i) {
        auto t0 = Clock::now();
        fn();
        auto t1 = Clock::now();
        times.push_back(std::chrono::duration<double, std::milli>(t1 - t0).count());
    }
    std::sort(times.begin(), times.end());
    return times[1]; // median
}

int main() {
    const int N = 10'000'000;

    std::mt19937_64 rng(42);
    std::uniform_real_distribution<double> dist(0.0, 1.0);

    // Generate reference data
    std::vector<double> data(N);
    for (int i = 0; i < N; ++i) data[i] = dist(rng);

    std::cout << "N = " << N << "\n\n";

    // std::sort
    auto d1 = data;
    double ms_std = measure_ms([&]() { std::sort(d1.begin(), d1.end()); });
    std::cout << "std::sort:             " << ms_std << " ms\n";
    bool ok1 = std::is_sorted(d1.begin(), d1.end());
    std::cout << "  Correct: " << (ok1 ? "yes" : "NO") << "\n\n";

    // Custom QuickSort (pure Hoare)
    auto d2 = data;
    double ms_custom = measure_ms([&]() { custom_quick_sort(d2); });
    std::cout << "Custom QuickSort:      " << ms_custom << " ms\n";
    bool ok2 = std::is_sorted(d2.begin(), d2.end());
    std::cout << "  Correct: " << (ok2 ? "yes" : "NO") << "\n";
    std::cout << "  Ratio:   " << (ms_custom / ms_std) << "x slower than std::sort\n\n";

    // Custom QuickSort + InsertionSort tail
    auto d3 = data;
    double ms_custom_hybrid = measure_ms([&]() { custom_quick_sort_hybrid_wrapper(d3); });
    std::cout << "Custom QS + Insertion: " << ms_custom_hybrid << " ms\n";
    bool ok3 = std::is_sorted(d3.begin(), d3.end());
    std::cout << "  Correct: " << (ok3 ? "yes" : "NO") << "\n";
    std::cout << "  Ratio:   " << (ms_custom_hybrid / ms_std) << "x slower than std::sort\n";

    return 0;
}
